@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-6px); }
}

@keyframes float-slow {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  33% { transform: translateY(-12px) rotate(2deg); }
  66% { transform: translateY(-6px) rotate(-1deg); }
}

@keyframes float-diagonal {
  0%, 100% { transform: translateY(0px) translateX(0px); }
  50% { transform: translateY(-20px) translateX(10px); }
}

.animate-float { animation: float 3s ease-in-out infinite; }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
.animate-float-diagonal { animation: float-diagonal 4s ease-in-out infinite; }

.sky-bg {
  background: linear-gradient(180deg, #87CEEB 0%, #B0E0E6 30%, #E3F2FD 60%, #FFFFFF 100%);
  position: relative;
  overflow: hidden;
}

.cloud {
  position: absolute;
  background: rgba(255,255,255,0.9);
  border-radius: 50%;
  filter: blur(1px);
}

.cloud::before,
.cloud::after {
  content: '';
  position: absolute;
  background: inherit;
  border-radius: 50%;
}

.cloud-layer-rear {
  animation: cloud-drift-rear 60s linear infinite;
}

.cloud-layer-front {
  animation: cloud-drift-front 30s linear infinite;
}

@keyframes cloud-drift-rear {
  0% { transform: translateX(-10%); }
  100% { transform: translateX(110%); }
}

@keyframes cloud-drift-front {
  0% { transform: translateX(110%); }
  100% { transform: translateX(-10%); }
}
